   7: //! Timestamp formatting.
   8: 
   9: use chrono::prelude::*;
  10: use core::cmp::max;
  11: use std::sync::LazyLock;
  12: use std::time::Duration;
  13: use unicode_width::UnicodeWidthStr;
  14: 
  15: /// Every timestamp in exa needs to be rendered by a **time format**.
  16: /// Formatting times is tricky, because how a timestamp is rendered can
  17: /// depend on one or more of the following:
  18: ///
  19: /// - The user’s locale, for printing the month name as “Feb”, or as “fév”,
  20: ///   or as “2月”;
  21: /// - The current year, because certain formats will be less precise when
  22: ///   dealing with dates far in the past;
  23: /// - The formatting style that the user asked for on the command-line.
  24: ///
  25: /// Because not all formatting styles need the same data, they all have their
  26: /// own enum variants. It’s not worth looking the locale up if the formatter
  27: /// prints month names as numbers.
  28: ///
  29: /// Also, eza supports *custom* styles, where the user enters a
  30: /// format string in an environment variable or something. Just these four.
  31: #[derive(PartialEq, Eq, Debug, Clone)]
  32: pub enum TimeFormat {
  33:     /// The **default format** uses the user’s locale to print month names,
  34:     /// and specifies the timestamp down to the minute for recent times, and
  35:     /// day for older times.
  36:     DefaultFormat,
  37: 
  38:     /// Use the **ISO format**, which specifies the timestamp down to the
  39:     /// minute for recent times, and day for older times. It uses a number
  40:     /// for the month so it doesn’t use the locale.
  41:     ISOFormat,
  42: 
  43:     /// Use the **long ISO format**, which specifies the timestamp down to the
  44:     /// minute using only numbers, without needing the locale or year.
  45:     LongISO,
  46: 
  47:     /// Use the **full ISO format**, which specifies the timestamp down to the
  48:     /// millisecond and includes its offset down to the minute. This too uses
  49:     /// only numbers so doesn’t require any special consideration.
  50:     FullISO,
  51: 
  52:     /// Use a relative but fixed width representation.
  53:     Relative,
  54: 
  55:     /// Use custom formats, optionally a different custom format can be
  56:     /// specified for recent times, otherwise the same custom format will be
  57:     /// used for both recent and non-recent times.
  58:     Custom {
  59:         non_recent: String,
  60:         recent: Option<String>,
  61:     },
  62: }
  63: 
  64: impl TimeFormat {
  65:     #[must_use]
  66:     pub fn format(self, time: &DateTime<FixedOffset>) -> String {
  67:         #[rustfmt::skip]
  68:         return match self {
  69:             Self::DefaultFormat                 => default(time),
  70:             Self::ISOFormat                     => iso(time),
  71:             Self::LongISO                       => long(time),
  72:             Self::FullISO                       => full(time),
  73:             Self::Relative                      => relative(time),
  74:             Self::Custom { non_recent, recent } => custom(
  75:                 time, non_recent.as_str(), recent.as_deref()
  76:             ),
  77:         };
  78:     }
  79: }
  80: 
  81: fn default(time: &DateTime<FixedOffset>) -> String {
  82:     let month = &*LOCALE.short_month_name(time.month0() as usize);
  83:     let month_width = short_month_padding(*MAX_MONTH_WIDTH, month);
  84:     let format = if time.year() == *CURRENT_YEAR {
  85:         format!("%_d {month:<month_width$} %H:%M")
  86:     } else {
  87:         format!("%_d {month:<month_width$}  %Y")
  88:     };
  89:     time.format(format.as_str()).to_string()
  90: }
  91: 
  92: /// Convert between Unicode width and width in chars to use in format!.
  93: /// ex: in Japanese, 月 is one character, but it has the width of two.
  94: /// For alignment purposes, we take the real display width into account.
  95: /// So, `MAXIMUM_MONTH_WIDTH` (“12月”) = 4, but if we use `{:4}` in format!,
  96: /// it will add a space (“ 12月”) because format! counts characters.
  97: /// Conversely, a char can have a width of zero (like combining diacritics)
  98: fn short_month_padding(max_month_width: usize, month: &str) -> usize {
  99:     let shift = month.chars().count() as isize - UnicodeWidthStr::width(month) as isize;
 100:     (max_month_width as isize + shift) as usize
 101: }
 102: 
 103: fn iso(time: &DateTime<FixedOffset>) -> String {
 104:     if time.year() == *CURRENT_YEAR {
 105:         time.format("%m-%d %H:%M").to_string()
 106:     } else {
 107:         time.format("%Y-%m-%d").to_string()
 108:     }
 109: }
 110: 
 111: fn long(time: &DateTime<FixedOffset>) -> String {
 112:     time.format("%Y-%m-%d %H:%M").to_string()
 113: }
 114: 
 115: // #[allow(trivial_numeric_casts)]
 116: fn relative(time: &DateTime<FixedOffset>) -> String {
 117:     timeago::Formatter::new()
 118:         .ago("")
 119:         .convert(Duration::from_secs(
 120:             max(0, Local::now().timestamp() - time.timestamp())
 121:                 // this .unwrap is safe since the call above can never result in a
 122:                 // value < 0
 123:                 .try_into()
 124:                 .unwrap(),
 125:         ))
 126: }
 127: 
 128: fn full(time: &DateTime<FixedOffset>) -> String {
 129:     time.format("%Y-%m-%d %H:%M:%S.%f %z").to_string()
 130: }
 131: 
 132: fn custom(time: &DateTime<FixedOffset>, non_recent_fmt: &str, recent_fmt: Option<&str>) -> String {
 133:     if let Some(recent_fmt) = recent_fmt {
 134:         if time.year() == *CURRENT_YEAR {
 135:             time.format(recent_fmt).to_string()
 136:         } else {
 137:             time.format(non_recent_fmt).to_string()
 138:         }
 139:     } else {
 140:         time.format(non_recent_fmt).to_string()
 141:     }
 142: }
 143: 
 144: static CURRENT_YEAR: LazyLock<i32> = LazyLock::new(|| Local::now().year());
 145: 
 146: static LOCALE: LazyLock<locale::Time> =
 147:     LazyLock::new(|| locale::Time::load_user_locale().unwrap_or_else(|_| locale::Time::english()));
 148: 
 149: static MAX_MONTH_WIDTH: LazyLock<usize> = LazyLock::new(|| {
 150:     // Some locales use a three-character wide month name (Jan to Dec);
 151:     // others vary between three to four (1月 to 12月, juil.). We check each month width
 152:     // to detect the longest and set the output format accordingly.
 153:     (0..11)
 154:         .map(|i| UnicodeWidthStr::width(&*LOCALE.short_month_name(i)))
 155:         .max()
 156:         .unwrap()
 331:             _ => Self::DecimalBytes,
 332:         })
 333:     }
 334: }
