 336: impl TimeFormat {
 337:     /// Determine how time should be formatted in timestamp columns.
 338:     fn deduce<V: Vars>(matches: &MatchedFlags<'_>, vars: &V) -> Result<Self, OptionsError> {
 339:         let word = if let Some(w) = matches.get(&flags::TIME_STYLE)? {
 340:             w.to_os_string()
 341:         } else {
 342:             match vars.get(vars::TIME_STYLE) {
 343:                 Some(ref t) if !t.is_empty() => t.clone(),
 344:                 _ => return Ok(Self::DefaultFormat),
 345:             }
 346:         };
 347: 
 348:         match word.to_string_lossy().as_ref() {
 349:             "default" => Ok(Self::DefaultFormat),
 350:             "relative" => Ok(Self::Relative),
 351:             "iso" => Ok(Self::ISOFormat),
 352:             "long-iso" => Ok(Self::LongISO),
 353:             "full-iso" => Ok(Self::FullISO),
 354:             fmt if fmt.starts_with('+') => {
 355:                 let mut lines = fmt[1..].lines();
 356: 
 357:                 // line 1 will be None when:
 358:                 //   - there is nothing after `+`
 359:                 // line 1 will be empty when:
 360:                 //   - `+` is followed immediately by `\n`
 361:                 let empty_non_recent_format_msg = "Custom timestamp format is empty, \
 362:                     please supply a chrono format string after the plus sign.";
 363:                 let non_recent = lines.next().expect(empty_non_recent_format_msg);
 364:                 let non_recent = if non_recent.is_empty() {
 365:                     panic!("{}", empty_non_recent_format_msg)
 366:                 } else {
 367:                     non_recent.to_owned()
 368:                 };
 369: 
 370:                 // line 2 will be None when:
 371:                 //   - there is not a single `\n`
 372:                 //   - there is nothing after the first `\n`
 373:                 // line 2 will be empty when:
 374:                 //   - there exist at least 2 `\n`, and no content between the 1st and 2nd `\n`
 375:                 let empty_recent_format_msg = "Custom timestamp format for recent files is empty, \
 376:                     please supply a chrono format string at the second line.";
 377:                 let recent = lines.next().map(|rec| {
 378:                     if rec.is_empty() {
 379:                         panic!("{}", empty_recent_format_msg)
 380:                     } else {
 381:                         rec.to_owned()
 382:                     }
 383:                 });
 384: 
 385:                 Ok(Self::Custom { non_recent, recent })
 386:             }
 387:             _ => Err(OptionsError::BadArgument(&flags::TIME_STYLE, word)),
 388:         }
 389:     }
 390: }
